import Foundation

extension AccessibilityGuides {
    static let services = DirectoryGuide(
        cardSummary: .init(ukrainian: "Доступний прийом, підтримка праці та захист прав", german: "Zugängliche Termine, Arbeitshilfe und Rechtsschutz"),
        introduction: .init(ukrainian: "Опишіть конкретний бар’єр і потрібний спосіб участі. Для доступності поїзда та допомоги в дорозі відкрийте окрему тему «Транспорт».", german: "Die konkrete Barriere und die benötigte Teilnahmeform benennen. Für Bahnzugang und Reisehilfe das eigene Thema „Transport“ öffnen."),
        sections: [
            .init("appointment", "building.2", "Підготуйте доступний прийом", "Zugänglichen Termin vorbereiten", "До візиту напишіть установі, що саме заважає: сходи, відсутність ліфта, недоступна форма, потреба в жестовому або письмовому перекладі. Попросіть конкретне рішення, дату та письмове підтвердження; перевірте також доступний туалет і шлях до входу. Загальне слово «безбар’єрно» не підтверджує, що потрібна саме вам частина послуги доступна.", "Vor dem Termin der Stelle die konkrete Hürde mitteilen: Stufen, fehlender Lift, unzugängliches Formular oder Bedarf an Gebärden- bzw. Schriftdolmetschung. Konkrete Lösung, Termin und schriftliche Bestätigung erbitten; auch WC und Weg zum Eingang prüfen. Die Angabe „barrierefrei“ allein bestätigt nicht, dass der benötigte Teil der Leistung nutzbar ist.", source: equality),
            .init("work-assistance", "person.2", "Асистент для роботи чи першого навчання", "Assistenz für Arbeit oder Erstausbildung", "Persönliche Assistenz am Arbeitsplatz може допомогти на роботі, при пошуку роботи, у професійному навчанні або першому навчанні у виші. Служба перевіряє індивідуальні умови, зокрема ступінь інвалідності або рівень Pflegegeld; регіональна Assistenz-Servicestelle організовує допомогу. Опишіть конкретні дії, з якими потрібна підтримка, і зверніться до земельного Sozialministeriumservice до початку послуги.", "Persönliche Assistenz am Arbeitsplatz kann bei Beruf, Arbeitssuche, Berufsausbildung oder Erststudium helfen. Die Stelle prüft individuelle Voraussetzungen, etwa Grad der Behinderung oder Pflegegeldstufe; die regionale Assistenz-Servicestelle vermittelt Hilfe. Benötigte Tätigkeiten konkret beschreiben und vor Beginn bei der Landesstelle des Sozialministeriumservice anfragen.", source: workAssistance),
            .init("workplace", "desktopcomputer", "Технічна адаптація робочого місця", "Technische Arbeitsplatzadaptierung", "Коли бар’єр стосується робочого місця, запитайте Sozialministeriumservice про фінансування потрібного обладнання, програмного забезпечення або навчання їх використанню. Поясніть зв’язок засобу з конкретною роботою, узгодьте з роботодавцем кошторис і подайте заявку до купівлі. Це окремий шлях від медичного Hilfsmittel, який призначає лікар і розглядає страхова каса.", "Betrifft die Barriere den Arbeitsplatz, beim Sozialministeriumservice Förderung für nötige Geräte, Software oder deren Einschulung erfragen. Zusammenhang mit konkreter Tätigkeit darlegen, Kostenvoranschlag mit dem Arbeitgeber abstimmen und vor dem Kauf anfragen. Das ist ein anderer Weg als ein ärztlich verordnetes medizinisches Hilfsmittel der Krankenkasse.", source: workplace),
            .init("mediation", "checkmark.shield", "Коли відмовили через бар’єр", "Wenn eine Barriere zur Benachteiligung führt", "Збережіть дату, місце, назву послуги, опис перешкоди та відповідь організації. При дискримінації через інвалідність можна звернутися до земельного Sozialministeriumservice із заявою на безплатну Schlichtung без адвоката. Інвалідність треба правдоподібно підтвердити, але Behindertenpass не є обов’язковим. Для строків подальших вимог отримайте консультацію своєчасно.", "Datum, Ort, Dienst, konkrete Barriere und Antwort der Organisation sichern. Bei Benachteiligung wegen Behinderung bei der Landesstelle des Sozialministeriumservice kostenlose Schlichtung ohne Anwalt beantragen. Die Behinderung ist glaubhaft zu machen, ein Behindertenpass ist aber nicht nötig. Wegen möglicher Fristen weitergehende Ansprüche rechtzeitig beraten lassen.", source: mediation),
            .init("advice", "person.crop.circle.badge.questionmark", "Де обговорити можливі права", "Wo Rechte besprechen", "Якщо не зрозуміло, чи ситуація є дискримінацією або яку вимогу подати, зверніться до Behindertenanwaltschaft. Вона консультує щодо дискримінації, має регіональні контакти й може підтримати під час Schlichtung; це не орган, що видає Behindertenpass. Для особистої зустрічі домовтеся про термін заздалегідь.", "Ist unklar, ob eine Benachteiligung vorliegt oder welcher Anspruch besteht, die Behindertenanwaltschaft kontaktieren. Sie berät zu Diskriminierung, hat regionale Kontakte und kann bei der Schlichtung unterstützen; sie stellt keinen Behindertenpass aus. Für ein persönliches Gespräch vorher einen Termin vereinbaren.", source: advocate)
        ], sources: [equality, workAssistance, workplace, mediation, advocate]
    )
}
